import React, { useState } from 'react';
import './/file-upload.component.css';

function FileUpload() {
  const [selectedFile, setSelectedFile] = useState(null);

  const handleFileChange = (event) => {
    setSelectedFile(event.target.files[0]);
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    if (selectedFile) {
      const formData = new FormData();
      formData.append('file', selectedFile);

      try {
        const response = await fetch('/upload', { 
          method: 'POST', 
          body: formData 
        });

        if (!response.ok) {
          throw new Error('Network response was not ok');
        }

        const data = await response.json(); 
        console.log('File uploaded successfully:', data);

      } catch (error) {
        console.error('Error uploading file:', error);
      }
    }
  };

  return (
    <div className='file-upload-container'>
      <label className='file-upload-label'> Drag the file here</label>
    <form onSubmit={handleSubmit}>
      <input className='file-upload-input'
        label ="Drag or select the file"
        type="file" 
        onChange={handleFileChange} 
      />
      <button className='file-upload-button' type="submit">Upload</button>
    </form>
    </div>
  );
}

export default FileUpload;
